import re

def build_result(answer_text, retrieved):
    # retrieved: list of {"text", "source", "page"} in the same order as [1], [2], ...
    cited = {int(n) for n in re.findall(r"\[(\d+)\]", answer_text)}
    valid = sorted(n for n in cited if 1 <= n <= len(retrieved))   # remove invented ids
    return {
        "answer": answer_text,
        "sources": [
            {"id": n, "source": retrieved[n-1]["source"],
             "page": retrieved[n-1]["page"], "text": retrieved[n-1]["text"]}
            for n in valid
        ],
    }

