import json

def check_output(output_text, must_contain, allowed_labels):
    """Return a list of problems. An empty list means all checks passed."""
    problems = []

    # 1. Valid JSON?
    try:
        data = json.loads(output_text)
    except json.JSONDecodeError:
        return ["Not valid JSON"]

    # 2. Required fields and types
    if "label" not in data:
        problems.append("Missing field: label")
    if "reason" not in data:
        problems.append("Missing field: reason")

    # 3. Allowed values
    if data.get("label") not in allowed_labels:
        problems.append(f"Bad label: {data.get('label')}")

    # 4. Keywords
    reason = str(data.get("reason", "")).lower()
    for word in must_contain:
        if word.lower() not in reason:
            problems.append(f"Missing keyword: {word}")

    # 5. Length
    if len(reason.split()) > 40:
        problems.append("Reason is longer than 40 words")

    return problems

